def transform(grid):
    # The horizontal divider separates two diagrams; the matching right-side
    # vertical marker color specifies the uniform result.
    for row in grid:
        for value in row:
            if value not in (0, 5):
                color = value
                break
        else:
            continue
        break
    return [[color, color], [color, color]]

